DROP TABLE IF EXISTS `tg_supplier_master`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tg_supplier_master` (
  `supplierId` bigint NOT NULL AUTO_INCREMENT,
  `supplierName` varchar(145) DEFAULT NULL,
  `companyDetails` varchar(245) DEFAULT NULL,
  `address` varchar(245) DEFAULT NULL,
  `cityId` bigint DEFAULT NULL,
  `countryId` bigint NOT NULL,
  `mobile` bigint DEFAULT NULL,
  `phone` bigint DEFAULT NULL,
  `email` varchar(255) CHARACTER SET ascii COLLATE ascii_general_ci DEFAULT NULL,
  `bankDetails` varchar(255) DEFAULT NULL,
  `gstDetails` varchar(255) DEFAULT NULL,
  `remarks` varchar(2000) DEFAULT NULL,
  `consolidator` tinyint DEFAULT NULL,
  `landPackage` tinyint DEFAULT NULL,
  `flight` tinyint DEFAULT NULL,
  `hotel` tinyint DEFAULT NULL,
  `transfers` tinyint DEFAULT NULL,
  `sightseeing` tinyint DEFAULT NULL,
  `visa` tinyint DEFAULT NULL,
  `insurance` tinyint DEFAULT NULL,
  `cruise` tinyint DEFAULT NULL,
  `others` tinyint DEFAULT NULL,
  `supplierRating` int DEFAULT NULL,
  `negotiates` tinyint DEFAULT NULL,
  `referredBy` varchar(255) DEFAULT NULL,
  `deleted` tinyint DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `lastUpdatedBy` int DEFAULT NULL,
  PRIMARY KEY (`supplierId`)
) ENGINE=InnoDB AUTO_INCREMENT=205 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

