  CONSTRAINT `FK_TRV_TO` FOREIGN KEY (`travelingTo`) REFERENCES `udndestinations` (`destinationId`)
) ENGINE=InnoDB AUTO_INCREMENT=300 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='This is the base deal table at a super high level and provides high level information about the deal. ';
