DROP TABLE IF EXISTS `udn_sts_manual_quotation`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `udn_sts_manual_quotation` (
  `manualSightSeeingQuotationId` bigint NOT NULL AUTO_INCREMENT,
  `quotationId` bigint DEFAULT NULL,
  `cityId` bigint DEFAULT NULL,
  `sightSeeingId` bigint DEFAULT NULL,
  `savedSightSeeing` tinyint DEFAULT NULL,
  `sightSeeingName` varchar(500) DEFAULT NULL,
  `sightSeeingDate` date DEFAULT NULL,
  `adults` int DEFAULT NULL,
  `children` int DEFAULT NULL,
  `infant` int DEFAULT NULL,
  `transferType` int DEFAULT NULL,
  `sightSeeingCost` int DEFAULT NULL,
  `sightSeeingMarkup` int DEFAULT NULL,
  `remarks` varchar(1500) DEFAULT NULL,
  `displayOrder` int DEFAULT NULL,
  `active` tinyint DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`manualSightSeeingQuotationId`),
  KEY `STS_QTN_ID_idx` (`quotationId`),
  CONSTRAINT `STS_QTN_ID` FOREIGN KEY (`quotationId`) REFERENCES `tg_quotations_recorder` (`quotationId`)
) ENGINE=InnoDB AUTO_INCREMENT=171 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

