  `supplierId` bigint DEFAULT NULL,
  `adults` int DEFAULT NULL,
  `children` int DEFAULT NULL,
  `infants` int DEFAULT NULL,
  `transferType` int DEFAULT NULL,
  `remarks` varchar(245) DEFAULT NULL,
  `status` int DEFAULT NULL,
  `savedSightSeeing` tinyint DEFAULT NULL,
  `serviceLineCost` float DEFAULT NULL,
  `markup` float DEFAULT NULL,
  `displayOrder` int DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`stsServiceId`),
  KEY `FK_STS_CTY_idx` (`cityId`),
  KEY `FK_STS_SRV_MAP_idx` (`serviceMapId`),
  KEY `FK_STS_SUPP_idx` (`supplierId`),
  KEY `FK_STS_STATUS_idx` (`status`),
  KEY `FK_STS_DEAL_CMF_idx` (`dealConfirmationId`),
  CONSTRAINT `FK_STS_CTY` FOREIGN KEY (`cityId`) REFERENCES `udndestinations` (`destinationId`),
  CONSTRAINT `FK_STS_DEAL_CMF` FOREIGN KEY (`dealConfirmationId`) REFERENCES `udn_deals_recorder` (`dealConfirmationId`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `FK_STS_SRV_MAP` FOREIGN KEY (`serviceMapId`) REFERENCES `udn_deal_service_map` (`serviceMapId`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `FK_STS_STATUS` FOREIGN KEY (`status`) REFERENCES `udn_deal_status` (`id`),
  CONSTRAINT `FK_STS_SUPP` FOREIGN KEY (`supplierId`) REFERENCES `tg_supplier_master` (`supplierId`)
) ENGINE=InnoDB AUTO_INCREMENT=81 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
